/* 内置兜底知识库（精选层20首·人工校准 + 24节气速查）*/
window.__ZHIJIE_MINI_POEMS=[{"title":"春晓","titleEn":"Spring Morning","author":"孟浩然","dynasty":"唐","lines":["春眠不觉晓，处处闻啼鸟。","夜来风雨声，花落知多少。"],"pinyin":["chūn mián bù jué xiǎo, chù chù wén tí niǎo.","yè lái fēng yǔ shēng, huā luò zhī duō shǎo."],"english":["Sleeping in spring, I missed the dawn; birds are singing everywhere.","Last night I heard wind and rain — how many flowers fell?"],"theme":["春天","小鸟","花","下雨","睡觉"],"themeEn":["spring","bird","flower","rain","sleep"]},{"title":"咏柳","titleEn":"Ode to the Willow","author":"贺知章","dynasty":"唐","lines":["碧玉妆成一树高，万条垂下绿丝绦。","不知细叶谁裁出，二月春风似剪刀。"],"pinyin":["bì yù zhuāng chéng yī shù gāo, wàn tiáo chuí xià lǜ sī tāo.","bù zhī xì yè shuí cái chū, èr yuè chūn fēng sì jiǎn dāo."],"english":["The tall willow looks dressed in green jade, with thousands of silky ribbons hanging down.","Who cut out these fine leaves? The spring wind of February — sharp as scissors!"],"theme":["柳树","春风","春天"],"themeEn":["willow","spring wind","spring"]},{"title":"村居","titleEn":"Village Life","author":"高鼎","dynasty":"清","lines":["草长莺飞二月天，拂堤杨柳醉春烟。","儿童散学归来早，忙趁东风放纸鸢。"],"pinyin":["cǎo zhǎng yīng fēi èr yuè tiān, fú dī yáng liǔ zuì chūn yān.","ér tóng sàn xué guī lái zǎo, máng chèn dōng fēng fàng zhǐ yuān."],"english":["Grass grows and orioles fly in the second month; willows by the bank sway in the spring mist.","Children come home early from school, hurrying to fly kites on the east wind."],"theme":["风筝","春天","儿童","柳树"],"themeEn":["kite","spring","children","willow"]},{"title":"清明","titleEn":"Qingming Festival","author":"杜牧","dynasty":"唐","lines":["清明时节雨纷纷，路上行人欲断魂。","借问酒家何处有，牧童遥指杏花村。"],"pinyin":["qīng míng shí jié yǔ fēn fēn, lù shàng xíng rén yù duàn hún.","jiè wèn jiǔ jiā hé chù yǒu, mù tóng yáo zhǐ xìng huā cūn."],"english":["Around Qingming, a soft drizzle keeps falling; travelers on the road feel heavy-hearted.","Asking where an inn might be, a little cowherd points far away — to Apricot Blossom Village."],"theme":["清明","下雨","牧童","杏花"],"themeEn":["qingming","rain","cowherd","apricot blossom"]},{"title":"小池","titleEn":"The Little Pond","author":"杨万里","dynasty":"宋","lines":["泉眼无声惜细流，树阴照水爱晴柔。","小荷才露尖尖角，早有蜻蜓立上头。"],"pinyin":["quán yǎn wú shēng xī xì liú, shù yīn zhào shuǐ ài qíng róu.","xiǎo hé cái lù jiān jiān jiǎo, zǎo yǒu qīng tíng lì shàng tóu."],"english":["A quiet spring lets water trickle gently; tree shadows love the soft sunny pond.","A little lotus bud just shows its pointy tip — and a dragonfly is already standing on it!"],"theme":["荷花","蜻蜓","夏天","池塘"],"themeEn":["lotus","dragonfly","summer","pond"]},{"title":"晓出净慈寺送林子方","titleEn":"West Lake in June","author":"杨万里","dynasty":"宋","lines":["毕竟西湖六月中，风光不与四时同。","接天莲叶无穷碧，映日荷花别样红。"],"pinyin":["bì jìng xī hú liù yuè zhōng, fēng guāng bù yǔ sì shí tóng.","jiē tiān lián yè wú qióng bì, yìng rì hé huā bié yàng hóng."],"english":["West Lake in June is truly special — its scenery is like no other season.","Lotus leaves reach the sky in endless green; lotus flowers glow extra red in the sun."],"theme":["荷花","西湖","夏天","莲叶"],"themeEn":["lotus","west lake","summer","lotus leaves"]},{"title":"所见","titleEn":"What I Saw","author":"袁枚","dynasty":"清","lines":["牧童骑黄牛，歌声振林樾。","意欲捕鸣蝉，忽然闭口立。"],"pinyin":["mù tóng qí huáng niú, gē shēng zhèn lín yuè.","yì yù bǔ míng chán, hū rán bì kǒu lì."],"english":["A cowherd rides his ox, his song ringing through the woods.","Wanting to catch a singing cicada, he suddenly shuts his mouth and stands still."],"theme":["牧童","蝉","夏天","黄牛"],"themeEn":["cowherd","cicada","summer","ox"]},{"title":"小儿垂钓","titleEn":"The Little Angler","author":"胡令能","dynasty":"唐","lines":["蓬头稚子学垂纶，侧坐莓苔草映身。","路人借问遥招手，怕得鱼惊不应人。"],"pinyin":["péng tóu zhì zǐ xué chuí lún, cè zuò méi tái cǎo yìng shēn.","lù rén jiè wèn yáo zhāo shǒu, pà dé yú jīng bù yìng rén."],"english":["A messy-haired child learns to fish, sitting side-on in the moss, half-hidden by grass.","When a passerby asks the way, he only waves — afraid to scare the fish, he says nothing."],"theme":["钓鱼","儿童","夏天"],"themeEn":["fishing","children","summer"]},{"title":"山行","titleEn":"A Mountain Walk","author":"杜牧","dynasty":"唐","lines":["远上寒山石径斜，白云生处有人家。","停车坐爱枫林晚，霜叶红于二月花。"],"pinyin":["yuǎn shàng hán shān shí jìng xié, bái yún shēng chù yǒu rén jiā.","tíng chē zuò ài fēng lín wǎn, shuāng yè hóng yú èr yuè huā."],"english":["A stone path winds up the cool mountain; homes appear where white clouds rise.","I stop my carriage to admire the maple woods at dusk — frosted leaves redder than spring flowers."],"theme":["枫叶","秋天","霜","山"],"themeEn":["maple","autumn","frost","mountain"]},{"title":"九月九日忆山东兄弟","titleEn":"Missing My Brothers on Double Ninth Day","author":"王维","dynasty":"唐","lines":["独在异乡为异客，每逢佳节倍思亲。","遥知兄弟登高处，遍插茱萸少一人。"],"pinyin":["dú zài yì xiāng wéi yì kè, měi féng jiā jié bèi sī qīn.","yáo zhī xiōng dì dēng gāo chù, biàn chā zhū yú shǎo yī rén."],"english":["Alone in a faraway land, I miss my family even more on festival days.","I know my brothers are climbing the hills, wearing dogwood — with one person missing: me."],"theme":["重阳","思念","登高","茱萸","秋天"],"themeEn":["double ninth","missing family","hiking","autumn"]},{"title":"枫桥夜泊","titleEn":"Night Mooring by Maple Bridge","author":"张继","dynasty":"唐","lines":["月落乌啼霜满天，江枫渔火对愁眠。","姑苏城外寒山寺，夜半钟声到客船。"],"pinyin":["yuè luò wū tí shuāng mǎn tiān, jiāng fēng yú huǒ duì chóu mián.","gū sū chéng wài hán shān sì, yè bàn zhōng shēng dào kè chuán."],"english":["The moon sets, crows caw, frost fills the sky; by riverside maples and fishing lights, I lie sleepless.","From Hanshan Temple outside Suzhou, the midnight bell reaches my boat."],"theme":["秋天","霜","月亮","枫树","夜晚"],"themeEn":["autumn","frost","moon","maple","night"]},{"title":"静夜思","titleEn":"Thoughts on a Quiet Night","author":"李白","dynasty":"唐","lines":["床前明月光，疑是地上霜。","举头望明月，低头思故乡。"],"pinyin":["chuáng qián míng yuè guāng, yí shì dì shàng shuāng.","jǔ tóu wàng míng yuè, dī tóu sī gù xiāng."],"english":["Bright moonlight before my bed — I thought it was frost on the ground.","I look up at the bright moon, then lower my head, thinking of home."],"theme":["月亮","思念","中秋","夜晚"],"themeEn":["moon","homesick","mid-autumn","night"]},{"title":"江雪","titleEn":"River Snow","author":"柳宗元","dynasty":"唐","lines":["千山鸟飞绝，万径人踪灭。","孤舟蓑笠翁，独钓寒江雪。"],"pinyin":["qiān shān niǎo fēi jué, wàn jìng rén zōng miè.","gū zhōu suō lì wēng, dú diào hán jiāng xuě."],"english":["No birds fly over the thousand mountains; no footprints on the ten thousand paths.","One old man in a straw cape, alone in a little boat, fishing in the snowy river."],"theme":["雪","冬天","钓鱼","江"],"themeEn":["snow","winter","fishing","river"]},{"title":"梅花","titleEn":"Plum Blossoms","author":"王安石","dynasty":"宋","lines":["墙角数枝梅，凌寒独自开。","遥知不是雪，为有暗香来。"],"pinyin":["qiáng jiǎo shù zhī méi, líng hán dú zì kāi.","yáo zhī bù shì xuě, wèi yǒu àn xiāng lái."],"english":["A few plum branches by the wall bloom all alone in the cold.","From far away I know they are not snow — a secret sweet scent drifts over."],"theme":["梅花","冬天","雪","香"],"themeEn":["plum blossom","winter","snow","fragrance"]},{"title":"元日","titleEn":"New Year’s Day","author":"王安石","dynasty":"宋","lines":["爆竹声中一岁除，春风送暖入屠苏。","千门万户曈曈日，总把新桃换旧符。"],"pinyin":["bào zhú shēng zhōng yī suì chú, chūn fēng sòng nuǎn rù tú sū.","qiān mén wàn hù tóng tóng rì, zǒng bǎ xīn táo huàn jiù fú."],"english":["Firecrackers crackle as the old year ends; spring wind brings warmth to the New Year wine.","The rising sun shines on every home, and everyone hangs new lucky charms for old."],"theme":["春节","过年","爆竹","春联"],"themeEn":["spring festival","chinese new year","firecracker","couplets"]},{"title":"悯农（其二）","titleEn":"Pity the Farmers","author":"李绅","dynasty":"唐","lines":["锄禾日当午，汗滴禾下土。","谁知盘中餐，粒粒皆辛苦。"],"pinyin":["chú hé rì dāng wǔ, hàn dī hé xià tǔ.","shuí zhī pán zhōng cān, lì lì jiē xīn kǔ."],"english":["Hoeing under the noon sun, sweat drips onto the soil below the seedlings.","Do you know? Every grain of rice on your plate comes from hard, hard work."],"theme":["农事","粮食","珍惜","夏天"],"themeEn":["farming","food","gratitude","summer"]},{"title":"登鹳雀楼","titleEn":"Climbing Stork Tower","author":"王之涣","dynasty":"唐","lines":["白日依山尽，黄河入海流。","欲穷千里目，更上一层楼。"],"pinyin":["bái rì yī shān jìn, huáng hé rù hǎi liú.","yù qióng qiān lǐ mù, gèng shàng yī céng lóu."],"english":["The white sun sets behind the mountains; the Yellow River flows to the sea.","To see a thousand miles farther, climb one more floor!"],"theme":["黄河","登高","励志","太阳"],"themeEn":["yellow river","climbing","inspiration","sun"]},{"title":"望庐山瀑布","titleEn":"Watching the Lushan Waterfall","author":"李白","dynasty":"唐","lines":["日照香炉生紫烟，遥看瀑布挂前川。","飞流直下三千尺，疑是银河落九天。"],"pinyin":["rì zhào xiāng lú shēng zǐ yān, yáo kàn pù bù guà qián chuān.","fēi liú zhí xià sān qiān chǐ, yí shì yín hé luò jiǔ tiān."],"english":["Sunlight on Incense Burner Peak makes purple mist; far off, a waterfall hangs like a ribbon.","It plunges three thousand feet — like the Milky Way falling from the sky!"],"theme":["瀑布","山","夏天","银河"],"themeEn":["waterfall","mountain","summer","milky way"]},{"title":"绝句","titleEn":"A Quatrain","author":"杜甫","dynasty":"唐","lines":["两个黄鹂鸣翠柳，一行白鹭上青天。","窗含西岭千秋雪，门泊东吴万里船。"],"pinyin":["liǎng gè huáng lí míng cuì liǔ, yī háng bái lù shàng qīng tiān.","chuāng hán xī lǐng qiān qiū xuě, mén bó dōng wú wàn lǐ chuán."],"english":["Two orioles sing in the green willow; a line of white egrets rises into the blue sky.","My window frames the western peaks’ ancient snow; by my door moor boats from ten thousand miles away."],"theme":["黄鹂","白鹭","春天","雪山","柳树"],"themeEn":["oriole","egret","spring","snow mountain","willow"]},{"title":"江南","titleEn":"Jiangnan (South of the River)","author":"汉乐府","dynasty":"汉","lines":["江南可采莲，莲叶何田田。","鱼戏莲叶间。","鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。"],"pinyin":["jiāng nán kě cǎi lián, lián yè hé tián tián.","yú xì lián yè jiān.","yú xì lián yè dōng, yú xì lián yè xī, yú xì lián yè nán, yú xì lián yè běi."],"english":["In Jiangnan we pick lotus; how lush and full the lotus leaves are!","Fish play among the lotus leaves.","Fish play east of the leaves, west of the leaves, south of the leaves, north of the leaves."],"theme":["采莲","莲叶","鱼","夏天","江南"],"themeEn":["lotus picking","lotus leaves","fish","summer","jiangnan"]}];
window.__ZHIJIE_MINI_TERMS=[{"name":"立春","date":"2月3日-5日","climate":"东风解冻，万物复苏，气温开始回升","eat":"春饼、春卷、萝卜，寓意\"咬春\"","doThing":"贴春联、迎春、打春牛","poemTitle":"立春","poemAuthor":"白玉蟾（宋）","poemContent":"东风吹散梅梢雪，一夜挽回天下春。从此阳春应有脚，百花富贵草精神。","keywords":["春天","复苏","春饼","迎春"]},{"name":"雨水","date":"2月18日-20日","climate":"降雨开始增多，气温回升较快","eat":"龙须饼、爆米花、红枣粥","doThing":"回娘屋、拉保保（认干爹）","poemTitle":"春夜喜雨","poemAuthor":"杜甫（唐）","poemContent":"好雨知时节，当春乃发生。随风潜入夜，润物细无声。","keywords":["春雨","播种","润物"]},{"name":"惊蛰","date":"3月5日-7日","climate":"春雷始鸣，气温回升，昆虫惊醒","eat":"梨子、炒豆、鸡蛋","doThing":"祭白虎、打小人、吃梨润肺","poemTitle":"观田家","poemAuthor":"韦应物（唐）","poemContent":"微雨众卉新，一雷惊蛰始。田家几日闲，耕种从此起。","keywords":["春雷","虫醒","桃花"]},{"name":"春分","date":"3月20日-22日","climate":"昼夜平分，春暖花开","eat":"春菜、汤圆、驴打滚","doThing":"竖蛋、放风筝、踏青","poemTitle":"春分日","poemAuthor":"徐铉（五代）","poemContent":"仲春初四日，春色正中分。绿野徘徊月，晴天断续云。","keywords":["昼夜平分","竖蛋","风筝"]},{"name":"清明","date":"4月4日-6日","climate":"天气晴朗，草木繁茂","eat":"青团、馓子、清明果","doThing":"扫墓祭祖、踏青郊游、插柳","poemTitle":"清明","poemAuthor":"杜牧（唐）","poemContent":"清明时节雨纷纷，路上行人欲断魂。借问酒家何处有，牧童遥指杏花村。","keywords":["扫墓","踏青","青团"]},{"name":"谷雨","date":"4月19日-21日","climate":"雨量增多，适合谷物生长","eat":"香椿、谷雨茶、菠菜","doThing":"赏牡丹、走谷雨、喝谷雨茶","poemTitle":"谷雨","poemAuthor":"朱槔（宋）","poemContent":"天点纷林际，虚檐写梦中。明朝知谷雨，无策禁花风。","keywords":["采茶","牡丹","播种"]},{"name":"立夏","date":"5月5日-7日","climate":"温度明显升高，炎暑将临","eat":"立夏蛋、立夏饭、蚕豆","doThing":"称体重、斗蛋、尝新","poemTitle":"立夏","poemAuthor":"陆游（宋）","poemContent":"赤帝收春半，祝融送夏来。日斜汤沐罢，熟练试单衣。","keywords":["夏天","称体重","立夏蛋"]},{"name":"小满","date":"5月20日-22日","climate":"夏熟作物籽粒开始饱满","eat":"苦菜、麦糕、桑葚","doThing":"祭车神、祈蚕节、看麦梢黄","poemTitle":"小满","poemAuthor":"欧阳修（宋）","poemContent":"夜莺啼绿柳，皓月醒长空。最爱垄头麦，迎风笑落红。","keywords":["麦子","饱满","苦菜"]},{"name":"芒种","date":"6月5日-7日","climate":"气温升高，雨量充沛，农事繁忙","eat":"青梅、粽子、杨梅","doThing":"送花神、安苗、煮梅","poemTitle":"芒种后积雨骤冷","poemAuthor":"范成大（宋）","poemContent":"梅霖倾泻九河翻，百渎交流海面宽。良苦吴农田下湿，年年披絮插秧寒。","keywords":["农忙","收麦","种稻"]},{"name":"夏至","date":"6月21日-22日","climate":"日长夜短，气温最高","eat":"凉面、馄饨、荔枝","doThing":"祭地、消夏避伏、吃凉面","poemTitle":"夏至避暑北池","poemAuthor":"韦应物（唐）","poemContent":"昼晷已云极，宵漏自此长。绿筠尚含粉，圆荷始散芳。","keywords":["白天最长","消暑","凉面"]},{"name":"小暑","date":"7月6日-8日","climate":"天气开始炎热，但还没到最热","eat":"莲藕、绿豆汤、西瓜","doThing":"晒书画、晒衣服、吃藕","poemTitle":"小暑六月节","poemAuthor":"元稹（唐）","poemContent":"倏忽温风至，因循小暑来。竹喧先觉雨，山暗已闻雷。","keywords":["炎热","晒伏","绿豆汤"]},{"name":"大暑","date":"7月22日-24日","climate":"一年中最热的时期","eat":"仙草、烧仙草、荔枝","doThing":"饮伏茶、晒伏姜、送大暑船","poemTitle":"大暑","poemAuthor":"曾几（宋）","poemContent":"赤日几时过，清风无处寻。经书聊枕籍，瓜李漫浮沉。","keywords":["最热","萤火虫","消暑"]},{"name":"立秋","date":"8月7日-9日","climate":"暑去凉来，秋意渐浓","eat":"西瓜、四季豆、秋桃","doThing":"贴秋膘、啃秋、晒秋","poemTitle":"立秋","poemAuthor":"刘翰（宋）","poemContent":"乳鸦啼散玉屏空，一枕新凉一扇风。睡起秋声无觅处，满阶梧叶月明中。","keywords":["秋天","贴秋膘","凉风"]},{"name":"处暑","date":"8月22日-24日","climate":"暑气渐消，天气转凉","eat":"鸭子、龙眼、白丸子","doThing":"放河灯、开渔节、出游迎秋","poemTitle":"处暑后风雨","poemAuthor":"仇远（宋）","poemContent":"疾风驱急雨，残暑扫除空。因识炎凉态，都来顷刻中。","keywords":["暑气消","河灯","秋凉"]},{"name":"白露","date":"9月7日-9日","climate":"天气转凉，露水凝结","eat":"白露茶、龙眼、番薯","doThing":"收清露、祭禹王、吃龙眼","poemTitle":"蒹葭","poemAuthor":"诗经·秦风","poemContent":"蒹葭苍苍，白露为霜。所谓伊人，在水一方。","keywords":["露水","秋凉","大雁"]},{"name":"秋分","date":"9月22日-24日","climate":"昼夜平分，秋高气爽","eat":"秋菜、汤圆、桂花酒","doThing":"竖蛋、吃秋菜、送秋牛","poemTitle":"秋词","poemAuthor":"刘禹锡（唐）","poemContent":"自古逢秋悲寂寥，我言秋日胜春朝。晴空一鹤排云上，便引诗情到碧霄。","keywords":["昼夜平分","竖蛋","秋高气爽"]},{"name":"寒露","date":"10月8日-9日","climate":"气温更低，露水更冷","eat":"菊花茶、芝麻、柿子","doThing":"登高、赏菊、饮菊花酒","poemTitle":"月夜梧桐叶上见寒露","poemAuthor":"戴察（唐）","poemContent":"萧疏桐叶上，月白露初团。滴沥清光满，荧煌素彩寒。","keywords":["菊花","登高","寒冷"]},{"name":"霜降","date":"10月23日-24日","climate":"天气渐冷，开始降霜","eat":"柿子、栗子、牛肉","doThing":"赏红叶、吃柿子、登高远眺","poemTitle":"霜降","poemAuthor":"元稹（唐）","poemContent":"霜降三旬后，蓂馀一叶秋。玄阴迎落日，凉魄尽残钩。","keywords":["降霜","柿子","红叶"]},{"name":"立冬","date":"11月7日-8日","climate":"水始冰，地始冻，冬季开始","eat":"饺子、羊肉、糍粑","doThing":"补冬、吃饺子、酿黄酒","poemTitle":"立冬","poemAuthor":"李白（唐）","poemContent":"冻笔新诗懒写，寒炉美酒时温。醉看墨花月白，恍疑雪满前村。","keywords":["冬天","饺子","保暖"]},{"name":"小雪","date":"11月22日-23日","climate":"开始降雪，雪量不大","eat":"腊肉、糍粑、刨汤","doThing":"腌腊肉、吃糍粑、晒鱼干","poemTitle":"小雪","poemAuthor":"戴叔伦（唐）","poemContent":"花雪随风不厌看，更多还肯失林峦。愁人正在书窗下，一片飞来一片寒。","keywords":["小雪","腊肉","糍粑"]},{"name":"大雪","date":"12月6日-8日","climate":"雪量增大，天气更冷","eat":"红薯粥、羊肉、萝卜","doThing":"腌肉、进补、赏雪","poemTitle":"江雪","poemAuthor":"柳宗元（唐）","poemContent":"千山鸟飞绝，万径人踪灭。孤舟蓑笠翁，独钓寒江雪。","keywords":["大雪","瑞雪","进补"]},{"name":"冬至","date":"12月21日-23日","climate":"日短夜长，数九寒天开始","eat":"饺子（北方）、汤圆（南方）、羊肉汤","doThing":"祭祖、数九、吃饺子/汤圆","poemTitle":"冬至","poemAuthor":"杜甫（唐）","poemContent":"年年至日长为客，忽忽穷愁泥杀人。江上形容吾独老，天边风俗自相亲。","keywords":["冬至","饺子","汤圆","数九"]},{"name":"小寒","date":"1月5日-7日","climate":"天气寒冷，但还没到最冷","eat":"腊八粥、糯米饭、羊肉","doThing":"探梅、吃腊八粥、准备年货","poemTitle":"小寒","poemAuthor":"元稹（唐）","poemContent":"小寒连大吕，欢鹊垒新巢。拾食寻河曲，衔紫绕树梢。","keywords":["寒冷","腊八粥","梅花"]},{"name":"大寒","date":"1月20日-21日","climate":"一年中最冷的时期","eat":"八宝饭、年糕、消寒糕","doThing":"除旧布新、准备年货、蒸供","poemTitle":"大寒出江陵西门","poemAuthor":"陆游（宋）","poemContent":"平明羸马出西门，淡日寒云久吐吞。醉面冲风惊易醒，重裘藏手取微温。","keywords":["最冷","年货","迎新年"]}];
